// MARK: - Fixtures

private func makeEscapedString() -> Value {
  var chars = [Character]()
  chars.reserveCapacity(1000)
  for i in 0..<1000 {
    if i % 10 == 0 {
      switch i % 40 {
      case 0: chars.append("\n")
      case 10: chars.append("\t")
      case 20: chars.append("\"")
      case 30: chars.append("\\")
      default: chars.append("a")
      }
    } else {
      chars.append(Character(UnicodeScalar(65 + (i % 26))!))
    }
  }
  return .string(String(chars))
}

private func makeDeeplyNested() -> Value {
  var value: Value = .string("leaf")
  for i in stride(from: 19, through: 0, by: -1) {
    value = .object([.string("level\(i)"): value])
  }
  return value
}

private func makeNumbersVaried() -> Value {
  let nums: [Value] = [
    .number(0),
    .number(1),
    .number(-1),
    .number(42),
    .number(-999),
    .number(123456789),
    .number(3.14159),
    .number(-0.001),
    .number(1.23e10),
    .number(1.23e-5),
    .number(-9.87e+15),
    .number(0.0),
  ]
  return .array(nums)
}


